package pagos;
import java.net.*;import java.net.http.*;import java.time.Duration;import java.util.Map;
public class JdkMercadoPagoHttpTransport implements MercadoPagoHttpTransport {private final HttpClient cliente;public JdkMercadoPagoHttpTransport(){this(HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).followRedirects(HttpClient.Redirect.NEVER).build());}JdkMercadoPagoHttpTransport(HttpClient c){cliente=c;}public Respuesta ejecutar(String metodo,URI uri,Map<String,String> headers,String cuerpo){try{HttpRequest.Builder b=HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(15));headers.forEach(b::header);b.method(metodo,cuerpo==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(cuerpo));HttpResponse<String> r=cliente.send(b.build(),HttpResponse.BodyHandlers.ofString());return new Respuesta(r.statusCode(),r.body());}catch(HttpTimeoutException e){throw new IllegalStateException("Mercado Pago no respondió dentro del tiempo esperado.");}catch(Exception e){Thread.currentThread().interrupt();throw new IllegalStateException("No se pudo comunicar con Mercado Pago.",e);}}}
